#!/bin/sh
# install_on_g5.sh (dev machine) - copy this folder to the G5 as ~/rung3/va_cap (persistent: /tmp is wiped on every G5 reboot, logs must never live there), build the recorder there (gcc 4.0.1: `gcc -dynamiclib ... -framework IOKit -framework CoreFoundation`) and run its self-test
# (a passive recording of the already-proven-safe Surface get_state). Nothing is played and no kext call besides get_state is made.
H=${1:-G5}; cd "`dirname "$0"`" || exit 1
T=`mktemp` && tar czf $T . && scp -q $T $H:rung3/va_cap.tgz && rm -f $T && ssh $H 'rm -rf $HOME/rung3/va_cap && mkdir -p $HOME/rung3/va_cap && cd $HOME/rung3/va_cap && tar xzf $HOME/rung3/va_cap.tgz && gcc -dynamiclib -o iokit_record_va.dylib iokit_record_va.c -framework IOKit -framework CoreFoundation && gcc -o record_selftest record_selftest.c -framework IOKit -framework CoreFoundation && IOKIT_RECORD_LOG=$HOME/rung3/va_cap/self.tsv DYLD_INSERT_LIBRARIES=$HOME/rung3/va_cap/iokit_record_va.dylib ./record_selftest && chmod +x *.command *.sh && echo INSTALL_OK'
